import { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { Loader2 } from "lucide-react";
import { toast } from "sonner";

import { useAuth } from "@/lib/auth-store";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RKLogo } from "@/components/RKLogo";

/**
 * Deliberately dark regardless of app theme — this is the brand's front door.
 * The RK mark plays its arrival choreography on load, then the sign-in card
 * fades up beneath it.
 */
export default function LoginPage() {
  const login = useAuth((s) => s.login);
  const user = useAuth((s) => s.user);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const from = (location.state as { from?: { pathname?: string } } | null)?.from?.pathname ?? "/";

  if (user) {
    navigate(from === "/login" ? "/dashboard" : from, { replace: true });
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    try {
      await login(username.trim(), password);
      toast.success("Welcome back");
      navigate("/dashboard", { replace: true });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Login failed");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="login-veil relative flex min-h-screen flex-col items-center justify-center bg-[#05070B] p-4 text-zinc-100">
      <div className="relative z-10 w-full max-w-sm space-y-8">
        <div className="group flex flex-col items-center gap-4 text-center">
          <RKLogo className="h-16 w-16 text-[#C3C9D4] transition-colors group-hover:text-white" />
          <div>
            <div className="text-lg font-semibold tracking-[0.34em]">MKR GAS</div>
            <div className="mt-1 text-[11px] uppercase tracking-[0.22em] text-zinc-500">
              Operations &amp; accounting
            </div>
          </div>
        </div>

        <form
          onSubmit={handleSubmit}
          className="space-y-4 rounded-xl border border-white/10 bg-white/[0.03] p-7 shadow-2xl backdrop-blur"
        >
          <div className="space-y-1.5">
            <Label htmlFor="username" className="text-xs uppercase tracking-wider text-zinc-400">
              Username
            </Label>
            <Input
              id="username"
              autoComplete="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              required
              autoFocus
              className="border-white/10 bg-white/[0.04] text-zinc-100 placeholder:text-zinc-600 focus-visible:ring-teal-400/50"
            />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="password" className="text-xs uppercase tracking-wider text-zinc-400">
              Password
            </Label>
            <Input
              id="password"
              type="password"
              autoComplete="current-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="border-white/10 bg-white/[0.04] text-zinc-100 focus-visible:ring-teal-400/50"
            />
          </div>
          <Button
            type="submit"
            className="w-full bg-teal-500 text-teal-950 hover:bg-teal-400"
            disabled={submitting}
          >
            {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
            Sign in
          </Button>
        </form>

        <p className="text-center text-[11px] uppercase tracking-[0.18em] text-zinc-600">
          Authorized staff only
        </p>
      </div>
    </div>
  );
}
