import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Loader2 } from "lucide-react";

import { api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { isoMonth } from "@/lib/utils";

export default function AuditLogPage() {
  const [month, setMonth] = useState(isoMonth());
  const q = useQuery({
    queryKey: ["audit", month],
    queryFn: () => api.audit(month),
  });

  const entries = q.data?.entries ?? [];

  return (
    <div className="space-y-6">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-semibold tracking-tight">Audit log</h1>
          <p className="text-sm text-muted-foreground">
            Every write, login attempt, and admin action is recorded here.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Label className="text-xs text-muted-foreground">Month</Label>
          <Input
            type="month"
            value={month}
            onChange={(e) => setMonth(e.target.value)}
            className="w-44"
          />
        </div>
      </header>

      <Card>
        <CardHeader>
          <CardTitle>Entries</CardTitle>
          <CardDescription>{entries.length} entries</CardDescription>
        </CardHeader>
        <CardContent>
          {q.isLoading ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" /> Loading…
            </div>
          ) : null}
          {entries.length === 0 ? (
            <div className="rounded-md border border-dashed py-10 text-center text-sm text-muted-foreground">
              No audit entries yet for {month}.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="text-xs uppercase text-muted-foreground">
                  <tr>
                    <th className="px-2 py-2 text-left">Time (UTC)</th>
                    <th className="px-2 py-2 text-left">Actor</th>
                    <th className="px-2 py-2 text-left">Action</th>
                    <th className="px-2 py-2 text-left">Path</th>
                  </tr>
                </thead>
                <tbody>
                  {entries
                    .slice()
                    .reverse()
                    .map((e, i) => (
                      <tr key={i} className="border-t">
                        <td className="px-2 py-2 number-tabular text-xs">
                          {e.ts.replace("T", " ").slice(0, 19)}
                        </td>
                        <td className="px-2 py-2">
                          <Badge variant="outline" className="mr-2 capitalize">
                            {e.actorRole}
                          </Badge>
                          @{e.actor}
                        </td>
                        <td className="px-2 py-2">
                          <Badge
                            variant={
                              e.action === "login-failed"
                                ? "destructive"
                                : e.action === "login"
                                  ? "success"
                                  : "secondary"
                            }
                          >
                            {e.action}
                          </Badge>
                        </td>
                        <td className="px-2 py-2 font-mono text-xs">{e.path ?? "--"}</td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
