/**
 * Tiny zustand store that controls the `dark` class on <html>.
 *
 * Three modes:
 *   - "light"   : force light
 *   - "dark"    : force dark
 *   - "system"  : follow prefers-color-scheme and react to its changes
 *
 * The chosen mode is persisted to localStorage so refreshes feel instant.
 * An inline script in index.html applies the class before React mounts so
 * there's no flash of the wrong theme.
 */
import { create } from "zustand";

export type ThemeMode = "light" | "dark" | "system";
const STORAGE_KEY = "mkrgas:theme";

function readStored(): ThemeMode {
  if (typeof window === "undefined") return "dark";
  const v = window.localStorage.getItem(STORAGE_KEY);
  if (v === "light" || v === "dark" || v === "system") return v;
  return "dark";
}

function resolveEffective(mode: ThemeMode): "light" | "dark" {
  if (mode === "system") {
    if (typeof window === "undefined") return "dark";
    return window.matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark";
  }
  return mode;
}

function applyEffective(effective: "light" | "dark") {
  if (typeof document === "undefined") return;
  const root = document.documentElement;
  if (effective === "dark") root.classList.add("dark");
  else root.classList.remove("dark");
}

interface ThemeStore {
  mode: ThemeMode;
  effective: "light" | "dark";
  setMode: (next: ThemeMode) => void;
  initialize: () => void;
}

export const useTheme = create<ThemeStore>((set, get) => ({
  mode: readStored(),
  effective: resolveEffective(readStored()),
  setMode: (next) => {
    try {
      window.localStorage.setItem(STORAGE_KEY, next);
    } catch {
      /* ignore */
    }
    const effective = resolveEffective(next);
    applyEffective(effective);
    set({ mode: next, effective });
  },
  initialize: () => {
    const mode = get().mode;
    const effective = resolveEffective(mode);
    applyEffective(effective);
    set({ effective });
    if (mode === "system" && typeof window !== "undefined") {
      const mq = window.matchMedia("(prefers-color-scheme: light)");
      const onChange = () => {
        if (get().mode !== "system") return;
        const nextEffective = mq.matches ? "light" : "dark";
        applyEffective(nextEffective);
        set({ effective: nextEffective });
      };
      mq.addEventListener("change", onChange);
    }
  },
}));
