/**
 * AI business brief (admin only). Sends the dashboard's already-computed
 * aggregates to the Worker, which asks Gemini for an owner's brief:
 * headline, observations, watchouts, next steps. The result is cached to
 * derived/insights/YYYY-MM-DD.json so it generates at most once per day
 * unless explicitly refreshed. The card NEVER hides itself: an unconfigured
 * worker shows setup instructions, and generation failures show inline.
 */
import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertTriangle, ArrowRight, Loader2, RefreshCw, Sparkles } from "lucide-react";

import { api } from "@/lib/api";
import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import type { InsightsResult } from "@/lib/types";

interface CachedInsights extends InsightsResult {
  generatedAt: string;
  generatedBy: string;
}

interface Props {
  date: string; // today, store-local
  username: string;
  /** Compact aggregates prepared by the dashboard. */
  summary: Record<string, unknown>;
  /** Data still loading — don't offer generation on partial numbers. */
  ready: boolean;
}

export function InsightsCard({ date, username, summary, ready }: Props) {
  const qc = useQueryClient();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const statusQ = useQuery({ queryKey: ["ai-status"], queryFn: () => api.aiStatus() });
  const geminiOff = statusQ.data?.gemini === false;

  const cacheQ = useQuery({
    queryKey: ["insights", date],
    queryFn: () => api.readData<CachedInsights>(`derived/insights/${date}.json`),
  });
  const cached = cacheQ.data?.exists ? cacheQ.data.data : undefined;

  async function generate() {
    setBusy(true);
    setError(null);
    try {
      const res = await api.insights(summary);
      const payload: CachedInsights = {
        ...res.result,
        generatedAt: new Date().toISOString(),
        generatedBy: username,
      };
      await api.writeData(
        `derived/insights/${date}.json`,
        payload,
        cacheQ.data?.sha ?? null,
        `AI brief for ${date}`,
      );
      qc.invalidateQueries({ queryKey: ["insights", date] });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Could not generate the brief");
    } finally {
      setBusy(false);
    }
  }

  return (
    <Card className="border-violet-500/25">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between gap-3">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Sparkles className="h-4 w-4 text-violet-500" /> AI business brief
              <Badge variant="secondary" className="shrink-0">
                AI (Gemini)
              </Badge>
            </CardTitle>
            <CardDescription>
              {cached
                ? `Generated ${new Date(cached.generatedAt).toLocaleString("en-CA", { dateStyle: "medium", timeStyle: "short" })}`
                : "A plain-English read on the last 30 days — margins, volume, store, expenses."}
            </CardDescription>
          </div>
          <Button
            size="sm"
            variant={cached ? "outline" : "default"}
            disabled={busy || !ready || geminiOff}
            onClick={generate}
          >
            {busy ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : cached ? (
              <RefreshCw className="h-3.5 w-3.5" />
            ) : (
              <Sparkles className="h-3.5 w-3.5" />
            )}
            {cached ? "Refresh" : busy ? "Thinking…" : "Generate"}
          </Button>
        </div>
        {geminiOff ? (
          <div className="mt-3 flex items-start gap-2 rounded-md border border-amber-400/40 bg-amber-50/40 p-3 text-xs dark:bg-amber-950/20">
            <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-amber-600 dark:text-amber-400" />
            <div className="space-y-1 text-muted-foreground">
              <p className="font-medium text-amber-700 dark:text-amber-300">
                AI is not configured on the worker.
              </p>
              <p>
                Set the repo secret <code className="rounded bg-secondary px-1">GEMINI_API_KEY</code>{" "}
                on RadhaKrishna0018/mkrgas (
                <code className="rounded bg-secondary px-1">
                  gh secret set GEMINI_API_KEY -R RadhaKrishna0018/mkrgas
                </code>
                ), then re-run the &quot;Deploy Cloudflare Worker&quot; workflow.
              </p>
            </div>
          </div>
        ) : null}
        {error ? (
          <p className="mt-3 text-xs font-medium text-red-600 dark:text-red-400" role="alert">
            {error}
          </p>
        ) : null}
      </CardHeader>
      {cached ? (
        <CardContent className="space-y-4 text-sm">
          <p className="font-medium">{cached.headline}</p>
          <ul className="space-y-1.5">
            {cached.bullets.map((b, i) => (
              <li key={i} className="flex gap-2 text-muted-foreground">
                <span className="mt-1 h-1.5 w-1.5 shrink-0 rounded-full bg-violet-400" />
                {b}
              </li>
            ))}
          </ul>
          {cached.watchouts.length > 0 ? (
            <div className="space-y-1.5 rounded-md border border-amber-400/30 bg-amber-50/30 p-3 dark:bg-amber-950/15">
              {cached.watchouts.map((w, i) => (
                <div key={i} className="flex gap-2 text-xs text-amber-700 dark:text-amber-300">
                  <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
                  {w}
                </div>
              ))}
            </div>
          ) : null}
          {cached.actions.length > 0 ? (
            <div className="space-y-1.5">
              {cached.actions.map((a, i) => (
                <div key={i} className="flex gap-2 text-xs text-muted-foreground">
                  <ArrowRight className="mt-0.5 h-3.5 w-3.5 shrink-0 text-violet-400" />
                  {a}
                </div>
              ))}
            </div>
          ) : null}
        </CardContent>
      ) : null}
    </Card>
  );
}
